Here is the commit message:
af_unix: Fix memleak of newsk in unix_stream_connect().

When prepare_peercred() fails in unix_stream_connect(),
unix_release_sock() is not called for newsk, and the memory
is leaked.

Let's move prepare_peercred() before unix_create1().

Fixes: fd0a109a0f6b ("net, pidfs: prepare for handing out pidfds for reaped sk->sk_peer_pid")
Signed-off-by: Kuniyuki Iwashima <kuniyu@google.com>
Link: https://patch.msgid.link/20260207232236.2557549-1-kuniyu@google.com
Signed-off-by: Paolo Abeni <pabeni@redhat.com>

Here is the root cause:
In `unix_stream_connect()`, `prepare_peercred()` is called after `unix_create1()` allocates `newsk`. If `prepare_peercred()` fails, the error path does not free `newsk`, causing a memory leak.

Here is the patch:

 static int unix_stream_connect(struct socket *sock, struct sockaddr_unsized *uaddr,
 			       int addr_len, int flags)
 {
 	struct sockaddr_un *sunaddr = (struct sockaddr_un *)uaddr;
 	struct sock *sk = sock->sk, *newsk = NULL, *other = NULL;
 	struct unix_sock *u = unix_sk(sk), *newu, *otheru;
 	struct unix_peercred peercred = {};
 	struct net *net = sock_net(sk);
 	struct sk_buff *skb = NULL;
 	unsigned char state;
 	long timeo;
 	int err;

 	err = unix_validate_addr(sunaddr, addr_len);
 	if (err)
 		goto out;

 	err = BPF_CGROUP_RUN_PROG_UNIX_CONNECT_LOCK(sk, uaddr, &addr_len);
 	if (err)
 		goto out;

 	if (unix_may_passcred(sk) && !READ_ONCE(u->addr)) {
 		err = unix_autobind(sk);
 		if (err)
 			goto out;
 	}

 	timeo = sock_sndtimeo(sk, flags & O_NONBLOCK);

-	/* First of all allocate resources.
-	 * If we will make it after state is locked,
-	 * we will have to recheck all again in any case.
-	 */
+	err = prepare_peercred(&peercred);
+	if (err)
+		goto out;

 	/* create new sock for complete connection */
 	newsk = unix_create1(net, NULL, 0, sock->type);
 	if (IS_ERR(newsk)) {
 		err = PTR_ERR(newsk);
 		goto out;
 	}

-	err = prepare_peercred(&peercred);
-	if (err)
-		goto out;
-
 	/* Allocate skb for sending to listening sock */
 	skb = sock_wmalloc(newsk, 1, 0, GFP_KERNEL);
 	if (!skb) {
 		err = -ENOMEM;
 		goto out_free_sk;
 	}

 restart:
 	/*  Find listening sock. */
 	other = unix_find_other(net, sunaddr, addr_len, sk->sk_type, flags);
 	if (IS_ERR(other)) {
 		err = PTR_ERR(other);
 		goto out_free_skb;
 	}

 	unix_state_lock(other);

 	/* Apparently VFS overslept socket death. Retry. */
 	if (sock_flag(other, SOCK_DEAD)) {
 		unix_state_unlock(other);
 		sock_put(other);
 		goto restart;
 	}

 	if (other->sk_state != TCP_LISTEN ||
 	    other->sk_shutdown & RCV_SHUTDOWN) {
 		err = -ECONNREFUSED;
 		goto out_unlock;
 	}

 	if (unix_recvq_full_lockless(other)) {
 		if (!timeo) {
 			err = -EAGAIN;
 			goto out_unlock;
 		}

 		timeo = unix_wait_for_peer(other, timeo);
 		sock_put(other);

 		err = sock_intr_errno(timeo);
 		if (signal_pending(current))
 			goto out_free_skb;

 		goto restart;
 	}

 	/* self connect and simultaneous connect are eliminated
 	 * by rejecting TCP_LISTEN socket to avoid deadlock.
 	 */
 	state = READ_ONCE(sk->sk_state);
 	if (unlikely(state != TCP_CLOSE)) {
 		err = state == TCP_ESTABLISHED ? -EISCONN : -EINVAL;
 		goto out_unlock;
 	}

 	unix_state_lock(sk);

 	if (unlikely(sk->sk_state != TCP_CLOSE)) {
 		err = sk->sk_state == TCP_ESTABLISHED ? -EISCONN : -EINVAL;
 		unix_state_unlock(sk);
 		goto out_unlock;
 	}

 	err = security_unix_stream_connect(sk, other, newsk);
 	if (err) {
 		unix_state_unlock(sk);
 		goto out_unlock;
 	}

 	/* The way is open! Fastly set all the necessary fields... */

 	sock_hold(sk);
 	unix_peer(newsk) = sk;
 	newsk->sk_state = TCP_ESTABLISHED;
 	newsk->sk_type = sk->sk_type;
 	newsk->sk_scm_recv_flags = other->sk_scm_recv_flags;
 	init_peercred(newsk, &peercred);

 	newu = unix_sk(newsk);
 	newu->listener = other;
 	RCU_INIT_POINTER(newsk->sk_wq, &newu->peer_wq);
 	otheru = unix_sk(other);

 	/* copy address information from listening to new sock
 	 *
 	 * The contents of *(otheru->addr) and otheru->path
 	 * are seen fully set up here, since we have found
 	 * otheru in hash under its lock.  Insertion into the
 	 * hash chain we'd found it in had been done in an
 	 * earlier critical area protected by the chain's lock,
 	 * the same one where we'd set *(otheru->addr) contents,
 	 * as well as otheru->path and otheru->addr itself.
 	 *
 	 * Using smp_store_release() here to set newu->addr
 	 * is enough to make those stores, as well as stores
 	 * to newu->path visible to anyone who gets newu->addr
 	 * by smp_load_acquire().  IOW, the same warranties
 	 * as for unix_sock instances bound in unix_bind() or
 	 * in unix_autobind().
 	 */
 	if (otheru->path.dentry) {
 		path_get(&otheru->path);
 		newu->path = otheru->path;
 	}
 	refcount_inc(&otheru->addr->refcnt);
 	smp_store_release(&newu->addr, otheru->addr);

 	/* Set credentials */
 	copy_peercred(sk, other);

 	sock->state	= SS_CONNECTED;
 	WRITE_ONCE(sk->sk_state, TCP_ESTABLISHED);
 	sock_hold(newsk);

 	smp_mb__after_atomic();	/* sock_hold() does an atomic_inc() */
 	unix_peer(sk)	= newsk;

 	unix_state_unlock(sk);

 	/* take ten and send info to listening sock */
 	spin_lock(&other->sk_receive_queue.lock);
 	__skb_queue_tail(&other->sk_receive_queue, skb);
 	spin_unlock(&other->sk_receive_queue.lock);
 	unix_state_unlock(other);
 	other->sk_data_ready(other);
 	sock_put(other);
 	return 0;

 out_unlock:
 	unix_state_unlock(other);
 	sock_put(other);
 out_free_skb:
 	consume_skb(skb);
 out_free_sk:
 	unix_release_sock(newsk, 0);
 out:
 	drop_peercred(&peercred);
 	return err;
 }



